        unvisited = set(customers)
        cur = depot
        while unvisited:
            nxt = min(unvisited, key=lambda j: (d(cur, j), j))
            ordered.append(nxt)
            unvisited.remove(nxt)
            cur = nxt

    routes = []
    route = []
    load = 0
    for c in ordered:
        dc = demand(c)
        if dc > capacity:
            if route:
                routes.append(route)
                route = []
                load = 0
            routes.append([c])
            continue
        if route and load + dc > capacity:
            routes.append(route)
            route = [c]
            load = dc
        else:
            route.append(c)
            load += dc
    if route:
        routes.append(route)

    def route_load(r):
        s = 0
        for c in r:
            s += demand(c)
        return s

    def route_cost(r):
        if not r:
            return 0
        total = d(depot, r[0])
        for i in range(len(r) - 1):
            total += d(r[i], r[i + 1])
        total += d(r[-1], depot)
        return total

    changed = True
    passes = 0
    while changed and passes < 4 * max(1, len(customers)):
        changed = False
        passes += 1
        i = 0
        while i < len(routes):
            if not routes[i]:
                i += 1
                continue
            moved = False
            ri = routes[i]
            li = route_load(ri)
            ci = route_cost(ri)
            pos = 0
            while pos < len(ri):
                c = ri[pos]
                dc = demand(c)
                best = None
                best_delta = 0
                for j in range(len(routes)):
                    rj = routes[j]
                    if i != j and route_load(rj) + dc > capacity:
                        continue
                    if i == j and len(ri) == 1:
                        continue
                    prev_i = depot if pos == 0 else ri[pos - 1]
                    next_i = depot if pos == len(ri) - 1 else ri[pos + 1]
                    delta_remove = d(prev_i, next_i) - d(prev_i, c) - d(c, next_i)
                    if i == j:
                        temp = ri[:pos] + ri[pos + 1:]
                        for ins in range(len(temp) + 1):
                            if ins == pos:
                                continue
                            prev_j = depot if ins == 0 else temp[ins - 1]
                            next_j = depot if ins == len(temp) else temp[ins]
                            delta_ins = d(prev_j, c) + d(c, next_j) - d(prev_j, next_j)
                            delta = delta_remove + delta_ins
                            if delta < best_delta or (delta == best_delta and (best is None or (j, ins) < best)):
                                best_delta = delta
                                best = (j, ins)
                    else:
                        for ins in range(len(rj) + 1):
                            prev_j = depot if ins == 0 else rj[ins - 1]
                            next_j = depot if ins == len(rj) else rj[ins]
                            delta_ins = d(prev_j, c) + d(c, next_j) - d(prev_j, next_j)
                            delta = delta_remove + delta_ins
                            if delta < best_delta or (delta == best_delta and (best is None or (j, ins) < best)):
                                best_delta = delta
                                best = (j, ins)
                if best is not None:
                    j, ins = best
                    if i == j:
                        temp = routes[i][:]
                        temp.pop(pos)
                        if ins > pos:
                            ins -= 1
                        temp.insert(ins, c)
                        routes[i] = temp
                    else:
                        routes[i].pop(pos)
                        routes[j].insert(ins, c)
                    changed = True
                    moved = True
                    break
                pos += 1
            if not moved:
                i += 1
            else:
                if i < len(routes) and not routes[i]:
                    routes.pop(i)

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    cleaned = []
    assigned = set()
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c in assigned:
                continue
            dc = demand(c)
            if load + dc <= capacity:
                nr.append(c)
                load += dc
                assigned.add(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    for c in customers:
        if c not in assigned:
            routes.append([c])
            assigned.add(c)

    return routes
